-- Stable Viaform identities, preserving FIG number + variant.
INSERT OR IGNORE INTO "ViaformSkill" ("id","discipline","apparatus","name","aliases","provenance","figElementDefinitionId","canonicalKey","status","createdAt","updatedAt") SELECT 'fig_element_'||"id",'WAG',"apparatus","name","aliases",'FIG',"id",'FIG:ELEMENT:'||"apparatus"||':'||"officialNumber"||':'||"variantKey","status",CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "FigElementDefinition" WHERE "packageId"='canonical_fig_wag_2025_2028';
INSERT OR IGNORE INTO "ViaformSkill" ("id","discipline","apparatus","name","aliases","provenance","figVaultDefinitionId","canonicalKey","status","createdAt","updatedAt") SELECT 'fig_vault_'||"id",'WAG','VAULT',"name","aliases",'FIG',"id",'FIG:VAULT:'||"officialNumber"||':'||"variantKey","status",CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "FigVaultDefinition" WHERE "packageId"='canonical_fig_wag_2025_2028';
